import * as THREE from 'three'
import { useMemo, useRef } from 'react'
import { useFrame } from 'react-three-fiber'

function drawEnvFace(ctx, faceIndex, poolColor, poolSpread, poolStrength) {
  const size = 256
  const isTop = faceIndex === 2
  const isBottom = faceIndex === 3
  const grad = ctx.createLinearGradient(0, 0, 0, size)

  const poolHex = `#${poolColor.getHexString()}`
  const warm = poolColor.clone()
  warm.lerp(new THREE.Color('#ffffff'), 0.35)
  const warmHex = `#${warm.getHexString()}`
  const spread = Math.max(0.02, Math.min(1, poolSpread))
  const strength = Math.max(0, Math.min(1.5, poolStrength))

  if (isTop) {
    const spotRadius = 0.08 + spread * 0.42
    const radial = ctx.createRadialGradient(size * 0.5, size * 0.12, 0, size * 0.5, size * 0.5, size * spotRadius)
    radial.addColorStop(0, warmHex)
    radial.addColorStop(0.35, poolHex)
    radial.addColorStop(1, '#8a9098')
    ctx.fillStyle = radial
    ctx.fillRect(0, 0, size, size)
    ctx.fillStyle = `rgba(255, 255, 255, ${0.08 + strength * 0.18})`
    ctx.fillRect(size * (0.5 - spread * 0.22), 0, size * spread * 0.44, size * (0.22 + spread * 0.35))
    return
  }

  if (isBottom) {
    grad.addColorStop(0, '#3a3a42')
    grad.addColorStop(1, '#0e1014')
    ctx.fillStyle = grad
    ctx.fillRect(0, 0, size, size)
    const floorGlow = ctx.createRadialGradient(size * 0.5, size * 0.2, 0, size * 0.5, size * 0.55, size * (0.12 + spread * 0.38))
    floorGlow.addColorStop(0, `rgba(${Math.round(poolColor.r * 255)}, ${Math.round(poolColor.g * 255)}, ${Math.round(poolColor.b * 255)}, ${0.12 + strength * 0.35})`)
    floorGlow.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = floorGlow
    ctx.fillRect(0, 0, size, size)
    return
  }

  grad.addColorStop(0, warmHex)
  grad.addColorStop(0.22 + spread * 0.18, poolHex)
  grad.addColorStop(0.55, '#707680')
  grad.addColorStop(1, '#1a1a20')
  ctx.fillStyle = grad
  ctx.fillRect(0, 0, size, size)

  const stripW = 0.08 + spread * 0.34
  ctx.fillStyle = `rgba(${Math.round(poolColor.r * 255)}, ${Math.round(poolColor.g * 255)}, ${Math.round(poolColor.b * 255)}, ${0.18 + strength * 0.42})`
  ctx.fillRect(size * (0.5 - stripW * 0.5), 0, size * stripW, size * (0.28 + spread * 0.42))
}

function createDynamicEnvMap() {
  const size = 256
  const images = []
  const contexts = []

  for (let i = 0; i < 6; i++) {
    const canvas = document.createElement('canvas')
    canvas.width = size
    canvas.height = size
    const ctx = canvas.getContext('2d')
    contexts.push(ctx)
    images.push(canvas)
  }

  const cube = new THREE.CubeTexture(images)
  cube.needsUpdate = true
  return { cube, contexts, images }
}

export default function SceneEnvironment({ envRef, poolSpreadRef, poolIntensityRef, poolColorRef, visualRef }) {
  const envBundle = useMemo(() => createDynamicEnvMap(), [])
  const poolColor = useRef(new THREE.Color('#f5e6d4'))
  const lastKey = useRef('')

  if (envRef) envRef.current = envBundle.cube

  useFrame(() => {
    const spread = poolSpreadRef?.current ?? 0.52
    const strength = (poolIntensityRef?.current ?? 0.62) * (visualRef?.current?.lightIntensity ?? 1.2)
    if (poolColorRef?.current) poolColor.current.copy(poolColorRef.current)
    else if (visualRef?.current) poolColor.current.set(visualRef.current.light)

    const key = `${spread.toFixed(3)}|${strength.toFixed(3)}|${poolColor.current.getHexString()}`
    if (key === lastKey.current) return
    lastKey.current = key

    for (let i = 0; i < 6; i++) {
      drawEnvFace(envBundle.contexts[i], i, poolColor.current, spread, strength)
    }
    envBundle.cube.needsUpdate = true
  })

  return null
}
