import * as THREE from 'three'
import React, { useRef, useEffect } from 'react'
import { useThree, useFrame } from 'react-three-fiber'
import lerp from 'lerp'
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer'
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass'
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass'
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass'
import { FXAAShader } from 'three/examples/jsm/shaders/FXAAShader'

const SSAA_SCALE = 2

export default function Effects({ visualRef }) {
  const composer = useRef()
  const bloomPass = useRef()
  const fxaaPass = useRef()
  const { scene, gl, size, camera } = useThree()

  useEffect(() => {
    gl.setClearColor(0x000000, 0)
    const w = Math.max(1, Math.floor(size.width * SSAA_SCALE))
    const h = Math.max(1, Math.floor(size.height * SSAA_SCALE))
    const comp = new EffectComposer(gl)
    comp.setSize(w, h)

    const renderPass = new RenderPass(scene, camera)
    const bloom = new UnrealBloomPass(new THREE.Vector2(w, h), 0.12, 0.85, 0.82)
    const fxaa = new ShaderPass(FXAAShader)
    fxaa.uniforms.resolution.value.set(1 / w, 1 / h)

    comp.addPass(renderPass)
    comp.addPass(bloom)
    comp.addPass(fxaa)

    composer.current = comp
    bloomPass.current = bloom
    fxaaPass.current = fxaa

    return () => {
      if (comp.renderTarget1) comp.renderTarget1.dispose()
      if (comp.renderTarget2) comp.renderTarget2.dispose()
    }
  }, [gl, scene, camera, size.width, size.height])

  useFrame(() => {
    if (!composer.current || !visualRef?.current) return

    const v = visualRef.current
    const poolScale = v.poolScale ?? 0.62
    const bloomMix = Math.min(1, poolScale * v.lightIntensity / 1.8)

    if (bloomPass.current) {
      const targetStrength = Math.min(1.35, (v.bloom ?? 0.14) * poolScale * 0.95)
      const targetThreshold = lerp(v.bloomThreshold ?? 0.72, 0.42, bloomMix * 0.35)
      const bloomLerp = 0.11
      bloomPass.current.strength = lerp(bloomPass.current.strength, targetStrength, bloomLerp)
      bloomPass.current.threshold = lerp(bloomPass.current.threshold, targetThreshold, bloomLerp)
      bloomPass.current.radius = lerp(bloomPass.current.radius, 0.38 + poolScale * 0.22, bloomLerp)
    }

    composer.current.render()
  }, 1)

  return null
}
